layers.vertex:
uniform float uResolveProgress;
attribute vec3 aO; attribute vec2 aT, aF; attribute float aS; uniform float uTime; uniform vec3 uAlly; varying vec2 vQ; varying float vClock, vA, vPk, vPh; vec3 anc(vec3 o, float at){ return at > .5 ? uAlly : o; }
  vec3 manP(vec3 A, float sl){ float th = sl*2.0944 + uTime*.35; vec3 off = vec3(cos(th), 0., sin(th))*.5;   /* each charge has its own place on a short orbit at shoulder height (over the head is reserved for CC) */
    return A + off + vec3(0., 1.55 + .05*sin(uTime*1.7 + sl*2.), 0.); }
  vec3 rayP(vec3 A, float f, float sl){ vec3 M = manP(A, sl), S0 = A + vec3(-1.2, 7.5, 4.2), C = M + vec3(-.4, 1.4, 2.8);
    return mix(mix(S0, C, f), mix(C, M, f), f); }
  float rayF(float x){ x = clamp(x, 0., 1.); return 1. - (1. - x)*(1. - x); }
    void main(){
      float u = uTime - aT.x - 0.100, r = uTime - aT.y; if (u < 0.){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec3 A = anc(aO, aF.x), p; float sz, a = 1.;
      vPk = 1.; vPh = 0.;
      if (u < 0.900){ p = rayP(A, rayF(u/0.900), aS); sz = .3; }
      else { p = manP(A, aS); float m = u - 0.900;
        sz = .4*(1. + .35*exp(-m*9.)); vPk = m < .033 ? 2.2 : 1. + .8*exp(-m*8.); vPh = 1.; }
      vClock = clamp(uResolveProgress,0.,1.);
      if (r >= 0.){
        if (aF.y > .5){ float k = clamp(r/.2, 0., 1.); if (r > .2){ gl_Position = vec4(2.,2.,2.,1.); return; }
          sz *= 1. - k*k; vPk = 1. + 1.2*(1. - k); }
        else { if (r > .35){ gl_Position = vec4(2.,2.,2.,1.); return; } a = 1. - r/.35; a *= a; sz *= 1. - .25*r/.35; }
      }
      vA = a;
      vec4 mv = viewMatrix*vec4(p, 1.); float c = cos(uTime*.4), s = sin(uTime*.4);
      mv.xy += mat2(c, -s, s, c)*position.xy*sz; vQ = position.xy; gl_Position = projectionMatrix*mv;
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vQ; varying float vClock, vA, vPk, vPh;
    void main(){                          // icon: 4-point star, thin diagonal glints, a fine circle around it, bright core
      vec2 q = vQ; float r = length(q), a = atan(q.y, q.x);
      float st = pow(abs(cos(a*2.)), 22.)*exp(-r*2.8) + pow(abs(cos(a*2. + .785)), 40.)*exp(-r*6.)*.5;
      float core = exp(-r*r*55.), halo = exp(-r*r*6.)*.2;
      float ang01 = fract(atan(q.x, q.y)/6.2832 + 1.);
      float clk = smoothstep(vClock + .004, vClock - .004, ang01);          /* the ring empties like a clock during the delay */
      float ring = exp(-pow((r - .46)/.018, 2.))*(.15 + 1.3*clk)*vPh;
      vec3 o = (uOrange*(st*1.05 + halo + ring*.9) + mix(uGold, vec3(1.), .45)*(core*1.5 + st*.35 + ring*.3))*vPk*vA;
      o *= smoothstep(1., .84, r);
      if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.); }

layers.vertex:
uniform float uResolveProgress;
attribute vec3 aO; attribute vec2 aT, aF; attribute float aS; uniform float uTime; uniform vec3 uAlly; varying float vS, vY, vF; vec3 anc(vec3 o, float at){ return at > .5 ? uAlly : o; }
  vec3 manP(vec3 A, float sl){ float th = sl*2.0944 + uTime*.35; vec3 off = vec3(cos(th), 0., sin(th))*.5;   /* each charge has its own place on a short orbit at shoulder height (over the head is reserved for CC) */
    return A + off + vec3(0., 1.55 + .05*sin(uTime*1.7 + sl*2.), 0.); }
  vec3 rayP(vec3 A, float f, float sl){ vec3 M = manP(A, sl), S0 = A + vec3(-1.2, 7.5, 4.2), C = M + vec3(-.4, 1.4, 2.8);
    return mix(mix(S0, C, f), mix(C, M, f), f); }
  float rayF(float x){ x = clamp(x, 0., 1.); return 1. - (1. - x)*(1. - x); }
    void main(){
      float u = uTime - aT.x - 0.100; if (u < 0. || u > 0.900 + .3){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec3 A = anc(aO, aF.x);
      float head = rayF(u/0.900), tail = max(0., head - .55) + max(0., u - 0.900)/.3;
      if (head - tail < .005){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float s = position.x*.5 + .5, f = mix(tail, head, s);
      vec3 P = rayP(A, f, aS), T = normalize(rayP(A, min(f + .01, 1.), aS) - rayP(A, max(f - .01, 0.), aS));
      vec3 side = normalize(cross(T, P - cameraPosition));
      vS = s; vY = position.y; vF = 1. - clamp((u - 0.900)/.3, 0., 1.);
      gl_Position = projectionMatrix*viewMatrix*vec4(P + side*position.y*(.03 + .22*s*(1. - s*.4)), 1.);
    }

layers.fragment:
uniform float uTime; uniform vec3 uGold, uOrange; varying float vS, vY, vF;
    void main(){ float lum = 0., hot = 0.;
      for (int i=0;i<3;i++){ float fi = float(i), y0 = (fi - 1.)*.42, L = .55 + .3*fract(fi*.61 + .2);
        float d = vY - y0*vS, w = .09 + .06*(1. - fi*.3);
        float along = smoothstep(1. - L, 1., vS)*pow(vS, 1.2);
        lum += exp(-d*d/(w*w))*along*(.7 + .3*sin(vS*14. - uTime*9. + fi*2.)); hot += exp(-d*d/(w*w*.12))*along*vS; }
      vec3 o = (uOrange*lum*.5 + mix(uGold, vec3(1.), .4)*hot*.35)*vF*(1. - smoothstep(.8, 1., abs(vY)));
      if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.); }
